#define bms_parser bms_base
#include "base/src/SHA256.h"
#undef bms_parser
#include "sha-arm/src/SHA256.h"
#include <algorithm>
#include <array>
#include <cstring>
#include <iostream>
#include <random>
#include <stdexcept>
using Digest = std::array<unsigned char, 32>;
template<class Hash> Digest digest(const unsigned char *data, size_t size, size_t chunk) {
  Hash hash; hash.init();
  for(size_t offset = 0; offset < size; offset += chunk)
    hash.update(data + offset, static_cast<unsigned>(std::min(chunk, size - offset)));
  Digest result; hash.final(result.data()); return result;
}
std::string hex(Digest d) { std::string s; for(auto x:d) {s += "0123456789abcdef"[x>>4];s += "0123456789abcdef"[x&15];}return s; }
void check(bool ok, const char *what) {if(!ok) throw std::runtime_error(what);}
struct BaseProbe: bms_base::SHA256 { using SHA256::transform; using SHA256::m_h; using SHA256::m_tot_len; };
struct ArmProbe: bms_parser::SHA256 { using SHA256::transform; using SHA256::m_h; using SHA256::m_tot_len; };
int main() {
 std::mt19937 rng(12345); size_t checks=0;
 const std::pair<std::string,std::string> known[]={
 {"","e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"},
 {"abc","ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad"},
 {"abcdbcdecdefdefgefghfghighijhijkijkljklmklmnlmnomnopnopq","248d6a61d20638b8e5c026930c3e6039a33ce45964ff2167f6ecedd419db06c1"},
 {std::string(1000000,'a'),"cdc76e5c9914fb9281a1c7e284d73e67f1809a48a497200e046d39ccc7112cd0"}};
 for(auto &v:known) { auto *p=reinterpret_cast<const unsigned char*>(v.first.data());for(size_t c:{size_t(1),size_t(7),size_t(64),size_t(4096)}) {check(hex(digest<bms_parser::SHA256>(p,v.first.size(),c))==v.second,"known vector");++checks;}}
 for(size_t n=0;n<1400;++n) {
  size_t len=n<1025?n:rng()%131073;std::vector<unsigned char> bytes(len+32);for(auto &b:bytes)b=static_cast<unsigned char>(rng());auto *p=bytes.data()+(n%32);
  auto expected=digest<bms_base::SHA256>(p,len,std::max(size_t(1),len));
  for(size_t c:{size_t(1),size_t(7),size_t(55),size_t(64),size_t(129),size_t(4096),std::max(size_t(1),len)}) {check(digest<bms_parser::SHA256>(p,len,c)==expected,"chunk/alignment equivalence");++checks;}
 }
 for(unsigned n=0;n<1000;++n) {
  unsigned blocks=rng()%33;std::vector<unsigned char> bytes(blocks*64+32);for(auto &b:bytes)b=static_cast<unsigned char>(rng());BaseProbe a;ArmProbe b;
  for(int i=0;i<8;++i)a.m_h[i]=b.m_h[i]=rng();a.transform(bytes.data()+n%32,blocks);b.transform(bytes.data()+n%32,blocks);check(std::memcmp(a.m_h,b.m_h,sizeof(a.m_h))==0,"raw compression");++checks;
 }
 // Exercise the legacy 32-bit length wrap in final() without allocating 512 MiB.
 for(unsigned total:{0u,0x1fffffc0u,0x20000000u,0xffffffc0u})for(unsigned tail=0;tail<64;++tail){BaseProbe a;ArmProbe b;a.init();b.init();a.m_tot_len=b.m_tot_len=total;std::array<unsigned char,64> bytes{};for(auto &x:bytes)x=static_cast<unsigned char>(rng());a.update(bytes.data(),tail);b.update(bytes.data(),tail);Digest x,y;a.final(x.data());b.final(y.data());check(x==y,"legacy length padding");++checks;}
 // Actual streamed input crosses the 512 MiB length-encoding boundary.
 bms_base::SHA256 streamBase; bms_parser::SHA256 streamArm;streamBase.init();streamArm.init();
 std::array<unsigned char,65536> chunk{};for(auto &x:chunk)x=static_cast<unsigned char>(rng());
 for(unsigned i=0;i<8191;++i){streamBase.update(chunk.data(),chunk.size());streamArm.update(chunk.data(),chunk.size());}
 streamBase.update(chunk.data(),65535);streamArm.update(chunk.data(),65535);
 for(unsigned extra=0;extra<3;++extra){if(extra){streamBase.update(chunk.data(),1);streamArm.update(chunk.data(),1);}auto a=streamBase;auto b=streamArm;Digest x,y;a.final(x.data());b.final(y.data());check(x==y,"actual 512 MiB boundary stream");++checks;std::cout<<"stream_bytes="<<(536870911u+extra)<<" digest="<<hex(x)<<"\n";}
 std::cout << "equivalence_checks=" << checks << " known_vectors=4 random_seed=12345\n";
}
